using System;
using System.Linq;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static partial class BlackoutTests
 {
  static GameState SubvertBoard()
  {
   var s=Make(true,true);Tile(s,1,1).unit!.type=Tile(s,1,1).unit!.UnitData.type=UnitType.dcp_spy;Add(s,9,2,1,2,UnitType.warrior);var ledger=Read(s);
   Write(s,ledger with{Units=ledger.Units.Append(new LedgerUnit(9,9,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,2)).ToArray()});return s;
  }
  static NativeExchangeIntent SubvertOffer(GameState s){Check(NativeSubvert.TryOffer(s,1,9,out var i,out var why),why);return i!;}
  static void SubvertCases()
  {
   Test("subvert-acquires-one-native-allowance-with-spent-neighbor",()=>{var s=SubvertBoard();var source=Tile(s,1,1).unit!;var relay=Tile(s,3,1).unit!;var target=Tile(s,2,1).unit!;relay.attacked=true;target.attacked=target.moved=true;var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);Check(source.attacked&&source.moved&&relay.attacked,"source spends once, neighboring Spy state unchanged");Check(target.owner==1&&!target.attacked&&!target.moved&&target.health==100,"target receives current player's allowance without body changes");var row=Read(s).Units.Single(u=>u.NativeId==9);Check(row.Rogue is {Owner:2,Commander:1} && row.Rogue.AcquiredTurn==s.CurrentTurn&&row.Acquisitions!.Single()==new LedgerAcquisition(1,s.CurrentTurn),"remembered owner and acquisition persist");Check(!Read(s).Units.Single(u=>u.NativeId==1).Independent&&Read(s).Units.Single(u=>u.NativeId==2).Independent,"only initiating Spy reveals");});
   foreach(var species in new[]{UnitType.dcp_spy,UnitType.dcp_spymaid})Test("subvert-neighbor-does-not-extend-range-"+species,()=>{var s=SubvertBoard();var source=Tile(s,1,1).unit!;source.type=source.UnitData.type=species;var near=SubvertOffer(s);var target=Tile(s,2,1).unit!;Tile(s,2,1).unit=null;target.coordinates=new(4,1);Tile(s,4,1).unit=target;var before=NativeGameStateEnvelope.Get(s)!;Check(!NativeSubvert.TryOffer(s,1,9,out _,out _),"adjacent Spy at three does not extend range to four");var remote=near with{Partner=near.Partner with{X=4,Y=1}};Check(!NativeSubvert.TryCommit(s,remote,out _,out _),"previously reachable relay intent cannot bypass direct range");Check(target.owner==2&&!source.moved&&!source.attacked&&ReferenceEquals(before,NativeGameStateEnvelope.Get(s)),"rejected range leaves ownership, allowance and ledger unchanged");});
   Test("subvert-receipt-retry-and-second-acquisition-denial",()=>{var s=SubvertBoard();var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out _),"first acquisition");var snapshot=NativeGameStateEnvelope.Get(s)!;Check(NativeSubvert.TryCommit(s,i,out var r,out _)&&r!.AlreadyCommitted&&ReferenceEquals(snapshot,NativeGameStateEnvelope.Get(s)),"exact replay does not regrant allowance");Tile(s,1,1).unit!.attacked=false;Tile(s,2,1).unit!.owner=2;Check(!NativeSubvert.TryOffer(s,1,9,out _,out _),"same-turn physical acquisition cannot be repeated");});
   foreach(string invalid in new[]{"treaty","hidden","dead","linked","owned","spent-source","frozen-source","unexplored-target","covered-target","outside-reach"})
    Test("subvert-denies-"+invalid,()=>{var s=SubvertBoard();var target=Tile(s,2,1).unit!;var source=Tile(s,1,1).unit!;switch(invalid){case"treaty":((PlayerState)Native.Items(s.PlayerStates).First()).Treaty=true;break;case"hidden":target.effects.Add(UnitEffect.Invisible);break;case"dead":target.health=0;break;case"linked":target.Linked=true;break;case"owned":target.owner=1;break;case"spent-source":source.attacked=true;break;case"frozen-source":source.effects.Add(UnitEffect.Frozen);break;case"unexplored-target":Tile(s,2,1).explorers=new();break;case"covered-target":Write(s,Read(s) with{Blackouts=new[]{new LedgerBlackout(1,2,1)}});break;case"outside-reach":Tile(s,2,1).unit=null;target.coordinates=new(11,7);Tile(s,11,7).unit=target;break;}Check(!NativeSubvert.TryOffer(s,1,9,out _,out _),"illegal target/source refused without action spend");Check(!source.moved&&target.owner==(invalid=="owned"?1:2),"no partial acquisition");});
   Test("frozen-target-keeps-native-incapacitation",()=>{var s=SubvertBoard();var t=Tile(s,2,1).unit!;t.effects.Add(UnitEffect.Frozen);var effects=t.effects;var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);Check(t.effects.Contains(UnitEffect.Frozen)&&ReferenceEquals(effects,t.effects),"acquisition does not thaw native status");Check(!NativeSpyNetwork.ActionReady(s,t,1),"frozen acquired body has no specialist action");});
   Test("rogue-resubversion-preserves-first-permanent-owner",()=>{var s=SubvertBoard();var target=Tile(s,2,1).unit!;target.owner=3;Write(s,Read(s) with{Units=Read(s).Units.Select(u=>u.NativeId==9?u with{Rogue=new(2,3,s.CurrentTurn-1),Acquisitions=new[]{new LedgerAcquisition(3,s.CurrentTurn-1)}}:u).ToArray()});var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);var r=Read(s).Units.Single(u=>u.NativeId==9);Check(r.Rogue is {Owner:2,Commander:1} && r.Rogue.AcquiredTurn==s.CurrentTurn&&r.Acquisitions!.Length==2,"new commander does not replace return owner or another player's history");});
   Test("acquired-spy-has-its-own-direct-range",()=>{var s=SubvertBoard();var target=Tile(s,2,1).unit!;target.type=UnitType.dcp_spy;var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);Check(NativeSpyNetwork.TryReachable(s,1,9,out var area,out _),"new genuine Spy can initiate");Check(area.Any(t=>NativeSpyNetwork.At(Native.Get(t,"coordinates")!)==new NativeSpyNetwork.Position(4,1)),"new Spy has its own radius immediately");});
   Test("acquired-stationary-spy-can-subvert-a-second-real-body",()=>{
    var s=SubvertBoard();var spy=Tile(s,2,1).unit!;spy.type=UnitType.dcp_spy;spy.UnitData.type=UnitType.dcp_spy;
    var second=Add(s,10,4,1,2,UnitType.warrior);Write(s,Read(s) with{Units=Read(s).Units.Append(new LedgerUnit(10,10,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,2)).ToArray()});
    var first=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,first,out _,out var why),why);
    Check(NativeSubvert.TryOffer(s,9,10,out var next,out why),why);Check(NativeSubvert.TryCommit(s,next!,out _,out why),why);
    Check(spy.attacked&&Tile(s,1,1).unit!.attacked&&second.owner==1&&!second.moved&&!second.attacked,"Chained Spy action spent only its own allowance and granted second body once");
    Check(Read(s).Units.Where(u=>u.NativeId is 9 or 10).All(u=>u.Rogue is {Owner:2,Commander:1}),"Chained Subvert lost permanent owners");
   });
   foreach(bool stale in new[]{false,true})Test("moved-spy-cannot-subvert-"+stale,()=>{var s=SubvertBoard();var i=stale?SubvertOffer(s):null;var source=Tile(s,1,1).unit!;source.moved=true;var before=NativeGameStateEnvelope.Get(s)!;Check(stale?!NativeSubvert.TryCommit(s,i!,out _,out _):!NativeSubvert.TryOffer(s,1,9,out _,out _),"moved disguised Spy cannot initiate");Check(source.moved&&!source.attacked&&Tile(s,2,1).unit!.owner==2&&ReferenceEquals(before,NativeGameStateEnvelope.Get(s)),"denied Subvert does not grant ownership or spend again");});
   Test("rogue-spy-movement-blocks-specialist-actions",()=>{var s=SubvertBoard();var spy=Tile(s,2,1).unit!;spy.type=UnitType.dcp_spy;spy.UnitData.type=UnitType.dcp_spy;var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);spy.moved=true;Check(!NativeSpyNetwork.TryReachable(s,1,9,out _,out _),"acquired moved Spy cannot initiate");Check(!NativeSubvert.TryOffer(s,9,1,out _,out _),"moved acquired Spy has no alternative initiating path");});
   foreach(var type in new[]{UnitType.dcp_spy,UnitType.dcp_spymaid})foreach(bool blackout in new[]{false})Test("spy-choice-move-or-act-"+type+"-"+blackout,()=>{var s=SubvertBoard();var source=Tile(s,1,1).unit!;source.type=source.UnitData.type=type;Check(blackout?NativeBlackout.TryOffer(s,1,2,1,out _,out _):NativeSubvert.TryOffer(s,1,9,out _,out _),"stationary specialist action allowed for either species");source.moved=true;Check(blackout?!NativeBlackout.TryOffer(s,1,2,1,out _,out _):!NativeSubvert.TryOffer(s,1,9,out _,out _),"movement spends specialist opportunity");source.moved=false;if(blackout)Cast(s,2,1);else {var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);}Check(source.moved&&source.attacked&&!NativeSpyNetwork.ActionReady(s,source,1),"specialist action spends movement and action");Check(!NativeSpyNetwork.TryReachable(s,1,1,out _,out _),"spent initiator has no specialist range");});
   Test("fake-spy-acquisition-does-not-grant-spy-actions",()=>{var s=SubvertBoard();var t=Tile(s,2,1).unit!;t.type=UnitType.dcp_mimic_form_dcp_spy;Write(s,Read(s) with{Units=Read(s).Units.Select(u=>u.NativeId==9?u with{Kind=LedgerActualKind.Mimic,Independent=true,Appearance=Mask() with{Form=SpyCatalog.Id}}:u).ToArray()});var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);Check(!NativeSpyNetwork.TryReachable(s,1,9,out _,out _),"acquired fake Spy remains actual Mimic");});
   Test("subvert-cargo-owner-and-allowance-follow-physical-vessel",()=>{var s=SubvertBoard();var t=Tile(s,2,1).unit!;t.type=UnitType.transportship;t.passengerUnit=new(){id=10,owner=2,type=UnitType.warrior,moved=true,attacked=true};t.moved=t.attacked=true;var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);Check(t.owner==1&&t.passengerUnit.owner==1&&!t.moved&&!t.attacked&&!t.passengerUnit.moved&&!t.passengerUnit.attacked,"root and cargo remain one allowance/owner context");});
   Test("subvert-local-scout-queues-discovery-in-same-candidate",()=>{var s=SubvertBoard();var target=Tile(s,2,1).unit!;target.type=UnitType.dcp_spy;Write(s,Read(s) with{Blackouts=new[]{new LedgerBlackout(1,3,1)}});Tile(s,3,1).explorers=new();var old=new ExploreAction{PlayerId=3,Coordinates=new(11,7)};s.ActionStack.Add(old);var i=SubvertOffer(s);Check(NativeSubvert.TryCommit(s,i,out _,out var why),why);Check(Native.Same(Native.Items(s.ActionStack).First(),old),"preexisting native queue prefix preserved");Check(Read(s).Discoveries!.Any(d=>d==new LedgerDiscovery(1,3,1))&&!Tile(s,3,1).GetExplored(1),"local actual Scout queues entitled fog discovery without executing it");Execute(s,Pending(s,1,3,1));Check(Tile(s,3,1).GetExplored(1),"native queued discovery clears permitted cell");});
   foreach(string stage in new[]{"validate","ledger"})Test("subvert-rollback-"+stage,()=>{var s=SubvertBoard();var t=Tile(s,2,1).unit!;t.moved=t.attacked=true;t.passengerUnit=new(){id=10,owner=2,moved=true,attacked=true};var i=SubvertOffer(s);var before=NativeGameStateEnvelope.Get(s)!;var queue=s.ActionStack;Fault.At=stage;Check(!NativeSubvert.TryCommit(s,i,out _,out _),"injected validation/publication failure");Check(t.owner==2&&t.moved&&t.attacked&&t.passengerUnit.owner==2&&t.passengerUnit.moved&&t.passengerUnit.attacked,"cargo and target exact preimages retained");Check(!Tile(s,1,1).unit!.attacked&&ReferenceEquals(queue,s.ActionStack)&&!s.HasFlaggedNeedForUpdateRoutes&&NativeGameStateEnvelope.Get(s)!.Bytes().SequenceEqual(before.Bytes()),"source/queue/routes/ledger restored");});
  }
 }
}
